// Email / invoice / revenue just finished from the Monthly Close pipeline.
// Leave Reports and put the focus card on the next unfinished apartment.
window.mcReturnAfterSend = function () {
  if (!_mcCtx) return false;
  var sentId = String(_mcCtx.id);
  _mcCtx = null;
  var bar = document.getElementById('mc-ctx-bar'); if (bar) bar.remove();
  var q = queue(), next = null;
  for (var i = 0; i < q.length; i++) {
    if (String(q[i].id) === sentId) continue;
    next = q[i]; break;
  }
  focusId = next ? next.id : null;
  if (typeof showTab === 'function') showTab('mt', document.querySelector('.nav-btn[data-tab="mt"]'));
  setTimeout(function () { try { renderMt(); } catch (e) {} }, 60);
  return true;
};

